package com.ferreteriahuaman.repository;
import com.ferreteriahuaman.dto.QuoteModels.*;import com.ferreteriahuaman.dto.CatalogModels.Page;import java.sql.*;import java.time.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import com.ferreteriahuaman.security.AuthFailure;
@Repository @Profile("db") public class QuoteRepository {
 private final JdbcTemplate jdbc;public QuoteRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private Map<String,Object> row(ResultSet r,int n)throws SQLException{var m=new LinkedHashMap<String,Object>();var meta=r.getMetaData();for(int i=1;i<=meta.getColumnCount();i++){Object v=r.getObject(i);if(v instanceof BigDecimal d)v=d.toPlainString();else if(v instanceof Timestamp t)v=t.toLocalDateTime().toString();else if(v instanceof java.sql.Date d)v=d.toLocalDate().toString();m.put(meta.getColumnLabel(i),v);}return m;}
 private static final String STATE="case when c.estado_cotizacion='VIGENTE' and c.vigente_hasta<timezone('America/Lima',now())::date then 'VENCIDA' else c.estado_cotizacion end";
 private static final String FROM=" from huaman.cotizacion c left join huaman.cliente cl on cl.id_cliente=c.id_cliente join huaman.usuario u on u.id_usuario=c.id_vendedor ";
 private static final String SELECT="select c.id_cotizacion id,c.numero,c.fecha,c.vigente_hasta \"vigenteHasta\",c.revision,c.id_vendedor \"vendedorId\",u.username vendedor,c.id_cliente \"clienteId\",cl.nro_documento documento,coalesce(cl.nombre_razon_social,nullif(c.nombre_interesado,''),'Sin identificar') cliente,c.nombre_interesado interesado,c.observacion,c.subtotal,c.descuento_total descuento,c.total,"+STATE+" estado,c.motivo_anulacion \"motivoAnulacion\",c.emitida_en \"emitidaEn\",c.anulada_en \"anuladaEn\",coalesce(c.fecmod,c.feccre) version,(select v.id_venta from huaman.venta v where v.id_cotizacion=c.id_cotizacion and v.estado='A') \"ventaId\",(select v.estado_venta from huaman.venta v where v.id_cotizacion=c.id_cotizacion and v.estado='A') \"estadoVenta\",(select v.id_vendedor from huaman.venta v where v.id_cotizacion=c.id_cotizacion and v.estado='A') \"ventaVendedorId\",timezone('America/Lima',now())::date hoy ";
 public Optional<Map<String,Object>> get(long id,boolean lock){return jdbc.query(SELECT+FROM+"where c.id_cotizacion=? and c.estado='A'"+(lock?" for update of c":""),this::row,id).stream().findFirst();}
 public Page<Map<String,Object>> list(long actor,boolean admin,String q,String state,LocalDate start,LocalDate end,int page,int size){String e=Character.toString(92),p="%"+q.replace(e,e+e).replace("%",e+"%").replace("_",e+"_")+"%",where="where c.estado='A' and (? or c.id_vendedor=?) and (?='' or "+STATE+"=?) and (?::date is null or c.fecha>=?) and (?::date is null or c.fecha<=?) and (c.numero::text ilike ? or coalesce(cl.nombre_razon_social,c.nombre_interesado,'') ilike ? or coalesce(cl.nro_documento,'') ilike ?)";Object[] args={admin,actor,state,state,start,start,end,end,p,p,p};long total=jdbc.queryForObject("select count(*)"+FROM+where,Long.class,args);var params=new ArrayList<Object>(Arrays.asList(args));params.add(size);params.add((long)page*size);return new Page<>(jdbc.query(SELECT+FROM+where+" order by c.id_cotizacion desc limit ? offset ?",this::row,params.toArray()),total,page,size);}
 public List<Map<String,Object>> lines(long id){return jdbc.query("select id_detalle_cotizacion id,id_producto \"productoId\",id_presentacion \"presentacionId\",producto_nombre producto,presentacion_nombre presentacion,unidad_base_simbolo unidad,cantidad,factor_base factor,cantidad_base \"cantidadBase\",precio_lista \"precioLista\",precio_unitario precio,origen_precio origen,descuento_monto descuento,importe from huaman.detalle_cotizacion where id_cotizacion=? and estado='A' order by id_detalle_cotizacion",this::row,id);}
 public int days(){Integer days=jdbc.query("select valor::integer from huaman.parametro_sistema where clave='COTIZACION.VIGENCIA_DIAS' and estado='A'",(r,n)->r.getInt(1)).stream().findFirst().orElse(null);if(days==null||days<1||days>90)throw new AuthFailure(409,"Configura una vigencia de cotización entre 1 y 90 días");return days;}
 public LocalDate today(){return jdbc.queryForObject("select timezone('America/Lima',now())::date",LocalDate.class);}
 private String clean(String s){return s==null||s.isBlank()?null:s.strip();}
 public long create(long actor,Save i){return jdbc.queryForObject("insert into huaman.cotizacion(id_cliente,nombre_interesado,id_vendedor,vigente_hasta,observacion) values(?,?,?,timezone('America/Lima',now())::date+?,?) returning id_cotizacion",Long.class,i.clienteId(),clean(i.interesado()),actor,days(),clean(i.observacion()));}
 public void update(long id,Save i){jdbc.update("update huaman.cotizacion set id_cliente=?,nombre_interesado=?,observacion=? where id_cotizacion=?",i.clienteId(),clean(i.interesado()),clean(i.observacion()),id);}
 public void replace(long id,List<Line> lines){jdbc.update("update huaman.detalle_cotizacion set estado='I' where id_cotizacion=? and estado='A'",id);for(var l:lines){int changed=jdbc.update("insert into huaman.detalle_cotizacion(id_cotizacion,id_producto,id_presentacion,cantidad) select ?,id_producto,id_presentacion,? from huaman.presentacion_producto where id_presentacion=? on conflict(id_cotizacion,id_presentacion) do update set cantidad=excluded.cantidad,estado='A'",id,l.cantidad(),l.presentacionId());if(changed!=1)throw new AuthFailure(400,"Una presentación ya no existe");}}
 public void lock(UUID key){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"QUOTE:"+key);}
 public Optional<Long> replay(long actor,String action,UUID key,String request){var rows=jdbc.queryForList("select (valor_nuevo->>'resultado')::bigint result,id_usuario=? and accion=? and valor_nuevo->'solicitud'=?::jsonb valid from huaman.bitacora_evento where referencia=?",actor,action,request,"QUOTE:"+key);if(rows.isEmpty())return Optional.empty();if(rows.size()!=1||!Boolean.TRUE.equals(rows.getFirst().get("valid")))throw new AuthFailure(409,"Esta clave ya corresponde a otra solicitud");return Optional.of(((Number)rows.getFirst().get("result")).longValue());}
 public void audit(long actor,String action,long entity,UUID key,String request,long result,String before,String after){jdbc.update("insert into huaman.bitacora_evento(id_usuario,accion,entidad,id_entidad,referencia,valor_anterior,valor_nuevo) values(?,?,'cotizacion',?,?,?::jsonb,jsonb_build_object('solicitud',?::jsonb,'resultado',?::bigint,'cotizacion',?::jsonb))",actor,action,entity,"QUOTE:"+key,before,request,result,after);}
 public long emit(long id,UUID key){return jdbc.queryForObject("select huaman.emitir_cotizacion(?,?)",Long.class,id,key);}
 public long cancel(long id,UUID key,String reason){return jdbc.queryForObject("select huaman.anular_cotizacion(?,?,?)",Long.class,id,key,reason);}
 public long recalculate(long id,int revision,UUID key){return jdbc.queryForObject("select huaman.recalcular_cotizacion(?,?,?)",Long.class,id,revision,key);}
 public void lockCash(long id){jdbc.queryForObject("select id_caja from huaman.caja_diaria where id_caja=? for update",Long.class,id);}
 public long convert(long id,long box,String type,UUID key){return jdbc.queryForObject("select huaman.convertir_cotizacion(?,?,?,?)",Long.class,id,box,type,key);}
}
